<script setup lang="ts">
import AcademicNav from '@/Components/AcademicNav.vue'; import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue'; import { Head, Link, useForm } from '@inertiajs/vue3';
const props = defineProps<{ framework?: any; providers: any[] }>(); const form = useForm({ education_provider_id: props.framework?.education_provider_id ?? null, name: props.framework?.name ?? '', short_name: props.framework?.short_name ?? '', jurisdiction: props.framework?.jurisdiction ?? '', version_label: props.framework?.version_label ?? 'unversioned', effective_start_date: props.framework?.effective_start_date ?? '', effective_end_date: props.framework?.effective_end_date ?? '', status: props.framework?.status ?? 'draft', source_url: props.framework?.source_url ?? '', notes: props.framework?.notes ?? '' }); const submit=()=>props.framework?form.patch(route('academic.standards.update',props.framework.id)):form.post(route('academic.standards.store'));
