<template><Head :title="framework ? 'Edit Standards Framework' : 'Add Standards Framework'" /><AuthenticatedLayout><h1 class="h2">{{ framework ? 'Edit custom framework' : 'Add custom framework' }}</h1><AcademicNav /><form class="card" @submit.prevent="submit"><div class="card-body"><div class="row g-3">
<div class="col-md-8"><label for="framework-name" class="form-label">Name</label><input id="framework-name" v-model="form.name" class="form-control" required><div v-if="form.errors.name" class="invalid-feedback d-block">{{ form.errors.name }}</div></div><div class="col-md-4"><label for="framework-short" class="form-label">Short name</label><input id="framework-short" v-model="form.short_name" class="form-control"></div>
