<div class="col-md-6"><label for="framework-provider" class="form-label">Provider</label><select id="framework-provider" v-model="form.education_provider_id" class="form-select"><option :value="null">No provider</option><option v-for="p in providers" :key="p.id" :value="p.id">{{p.name}}{{p.tenant_id===null?' (shared)':''}}</option></select></div><div class="col-md-6"><label for="framework-url" class="form-label">Source URL</label><input id="framework-url" v-model="form.source_url" type="url" class="form-control"></div>
